using WebApplication1.Helpers;
using Application.MainBoundedContext.DTO; using Application.MainBoundedContext.InventoryModule.Services; using Infrastructure.Crosscutting.Framework.Utils; using System; using System.Net; using System.Threading.Tasks; using System.Web.Http; namespace WebApplication1.Areas.Control.Controllers { [Authorize][RoutePrefix("api/control/assets")] public class AssetCatalogueController:ApiController { readonly IAssetAppService service; public AssetCatalogueController(IAssetAppService s){service=s;} [HttpGet][Route("")] public async Task<IHttpActionResult> Get(string text="",int pageIndex=0,int pageSize=20){try{return Ok(new{success=true,message="",data=await service.FindAsync(text,pageIndex,pageSize,Utils.CreateServiceHeader())});}catch(Exception){return Content(HttpStatusCode.InternalServerError,new{success=false,message="Unable to load assets.",data=(object)null});}} [HttpGet][Route("{id:guid}")] public async Task<IHttpActionResult> Get(Guid id){var x=await service.FindAsync(id,Utils.CreateServiceHeader());return x==null?(IHttpActionResult)NotFound():Ok(new{success=true,message="",data=x});} [HttpPost][Route("")] public async Task<IHttpActionResult> Post(AssetDTO dto){try{var x=await service.AddAsync(dto,Utils.CreateServiceHeader());return Content(HttpStatusCode.Created,new{success=true,message="Asset created successfully.",data=x});}catch(InvalidOperationException e){return Content(HttpStatusCode.BadRequest,new{success=false,message=e.Message,data=(object)null});}} [HttpPut][Route("{id:guid}")] public async Task<IHttpActionResult> Put(Guid id,AssetDTO dto){try{dto.Id=id;if(!await service.UpdateAsync(dto,Utils.CreateServiceHeader()))return NotFound();return Ok(new{success=true,message="Asset updated successfully.",data=await service.FindAsync(id,Utils.CreateServiceHeader())});}catch(InvalidOperationException e){return Content(HttpStatusCode.BadRequest,new{success=false,message=e.Message,data=(object)null});}} [HttpGet][Route("{id:guid}/depreciation-preview")] public async Task<IHttpActionResult> Preview(Guid id,DateTime periodDate){try{var x=await service.PreviewDepreciationAsync(id,periodDate,Utils.CreateServiceHeader());return x==null?(IHttpActionResult)NotFound():Ok(new{success=true,message="",data=x});}catch(InvalidOperationException e){return Content(HttpStatusCode.Conflict,new{success=false,message=e.Message,data=(object)null});}} [HttpPost][Route("{id:guid}/depreciation")] public async Task<IHttpActionResult> Depreciate(Guid id,DateTime periodDate){try{var x=await service.PostDepreciationAsync(id,periodDate,Utils.CreateServiceHeader());return x==null?(IHttpActionResult)NotFound():Ok(new{success=true,message="Depreciation posted successfully.",data=x});}catch(InvalidOperationException e){return Content(HttpStatusCode.Conflict,new{success=false,message=e.Message,data=(object)null});}} } }
